/// The code in an error answer, {error:{code,message},requestId}, and its HTTP status. unauthorized (a bad hook key), paused (a paused hook), badDeliveryId and full (its queue) come from the computer's relay, on /v1/hooks only.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum ErrorCode {
    BadRequest,
    BadDeliveryId,
    Unauthenticated,
    BadSignature,
    Unauthorized,
    Forbidden,
    AccountDeleted,
    NotFound,
    UnknownComputer,
    AlreadyClaimed,
    Conflict,
    TooMany,
    InviteUsed,
    Paused,
    ClaimExpired,
    RequestExpired,
    InviteExpired,
    InviteRevoked,
    TooLarge,
    UpgradeRequired,
    RateLimited,
    Full,
    Internal,
    ScreenRelayUnavailable,
    /// A code this version doesn't know.
    Unknown,
}

impl ErrorCode {
    pub fn from_code(code: &str) -> Self {
        match code {
            "badRequest" => Self::BadRequest,
            "badDeliveryId" => Self::BadDeliveryId,
            "unauthenticated" => Self::Unauthenticated,
            "badSignature" => Self::BadSignature,
            "unauthorized" => Self::Unauthorized,
            "forbidden" => Self::Forbidden,
            "accountDeleted" => Self::AccountDeleted,
            "notFound" => Self::NotFound,
            "unknownComputer" => Self::UnknownComputer,
            "alreadyClaimed" => Self::AlreadyClaimed,
            "conflict" => Self::Conflict,
            "tooMany" => Self::TooMany,
            "inviteUsed" => Self::InviteUsed,
            "paused" => Self::Paused,
            "claimExpired" => Self::ClaimExpired,
            "requestExpired" => Self::RequestExpired,
            "inviteExpired" => Self::InviteExpired,
            "inviteRevoked" => Self::InviteRevoked,
            "tooLarge" => Self::TooLarge,
            "upgradeRequired" => Self::UpgradeRequired,
            "rateLimited" => Self::RateLimited,
            "full" => Self::Full,
            "internal" => Self::Internal,
            "screenRelayUnavailable" => Self::ScreenRelayUnavailable,
            _ => Self::Unknown,
        }
    }

    pub const fn as_str(self) -> &'static str {
        match self {
            Self::BadRequest => "badRequest",
            Self::BadDeliveryId => "badDeliveryId",
            Self::Unauthenticated => "unauthenticated",
            Self::BadSignature => "badSignature",
            Self::Unauthorized => "unauthorized",
            Self::Forbidden => "forbidden",
            Self::AccountDeleted => "accountDeleted",
            Self::NotFound => "notFound",
            Self::UnknownComputer => "unknownComputer",
            Self::AlreadyClaimed => "alreadyClaimed",
            Self::Conflict => "conflict",
            Self::TooMany => "tooMany",
            Self::InviteUsed => "inviteUsed",
            Self::Paused => "paused",
            Self::ClaimExpired => "claimExpired",
            Self::RequestExpired => "requestExpired",
            Self::InviteExpired => "inviteExpired",
            Self::InviteRevoked => "inviteRevoked",
            Self::TooLarge => "tooLarge",
            Self::UpgradeRequired => "upgradeRequired",
            Self::RateLimited => "rateLimited",
            Self::Full => "full",
            Self::Internal => "internal",
            Self::ScreenRelayUnavailable => "screenRelayUnavailable",
            Self::Unknown => "unknown",
        }
    }

    pub const fn status(self) -> Option<u16> {
        match self {
            Self::BadRequest | Self::BadDeliveryId => Some(400),
            Self::Unauthenticated | Self::BadSignature | Self::Unauthorized => Some(401),
            Self::Forbidden | Self::AccountDeleted => Some(403),
            Self::NotFound | Self::UnknownComputer => Some(404),
            Self::AlreadyClaimed | Self::Conflict | Self::TooMany | Self::InviteUsed | Self::Paused => Some(409),
            Self::ClaimExpired | Self::RequestExpired | Self::InviteExpired | Self::InviteRevoked => Some(410),
            Self::TooLarge => Some(413),
            Self::UpgradeRequired => Some(426),
            Self::RateLimited | Self::Full => Some(429),
            Self::Internal => Some(500),
            Self::ScreenRelayUnavailable => Some(503),
            Self::Unknown => None,
        }
    }
}

